private struct Domain: Identifiable, Sendable {
    let id: String
    let name: String
    let status: String
    let owner: String
    let expires: String

    func value(_ column: String) -> String {
        switch column {
        case "name": name
        case "status": status
        case "owner": owner
        default: expires
        }
    }
}

private static let columns: [(id: String, title: String, isHideable: Bool, isHidden: Bool)] = [
    ({{columns.0.id}}, {{columns.0.header}}, {{columns.0.hideable}}, {{columns.0.defaultHidden}}),
    ({{columns.1.id}}, {{columns.1.header}}, {{columns.1.hideable}}, {{columns.1.defaultHidden}}),
    ({{columns.2.id}}, {{columns.2.header}}, {{columns.2.hideable}}, {{columns.2.defaultHidden}}),
    ({{columns.3.id}}, {{columns.3.header}}, {{columns.3.hideable}}, {{columns.3.defaultHidden}}),
]
private let domains = [
    Domain(id: {{rows.0.id}}, name: {{rows.0.name}}, status: {{rows.0.status}}, owner: {{rows.0.owner}}, expires: {{rows.0.expires}}),
    Domain(id: {{rows.1.id}}, name: {{rows.1.name}}, status: {{rows.1.status}}, owner: {{rows.1.owner}}, expires: {{rows.1.expires}}),
]
@State private var visible = Set(Self.columns.filter { !$0.isHidden }.map(\.id))

private func shown(_ id: String) -> Binding<Bool> {
    Binding(
        get: { visible.contains(id) },
        set: { isOn in
            if isOn { visible.insert(id) } else { visible.remove(id) }
        }
    )
}

